import requests
import json
import os
from azure.identity import DefaultAzureCredential, CertificateCredential
from typing import Dict, Any


import logging

log_level = os.getenv('METIQ_LOG_LEVEL', 'INFO').upper()
log_file = os.getenv('METIQ_LOG_FILE', 'metiq_api.log')

logging.basicConfig(
    level=log_level,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s",
    handlers=[logging.FileHandler(log_file), logging.StreamHandler()],
)

DEFAULT_AZURE_TENANT_ID = "ca56a4a5-e300-406a-98ff-7e36a0baac5b"

class MetIQAPI:
    def __init__(self, base_url, azure_client_id=None, apim_subscription_key=None, session=None, verify=True, certificate_path=None, certificate_password=None, certificate_scope=None, certificate_tenant=DEFAULT_AZURE_TENANT_ID):
        """Initialize the MetIQAPI instance.
        Args:
            base_url (str): The base URL for the API.
            token (str): The authorization token for the API.
        """
        self.base_url = base_url
        self.azure_client_id = azure_client_id
        self.apim_subscription_key = apim_subscription_key
        self.logger = logging.getLogger(self.__class__.__name__)
        self.session = session or requests.Session()
        self.certificate_path = certificate_path
        self.certificate_password = certificate_password
        self.certificate_scope = certificate_scope
        self.certificate_tenant = certificate_tenant
        
        # Set session-level verify
        self.session.verify = verify
        self.logger.info("Initialized MetIQAPI with base_url: %s", base_url)

    def build_headers(
        self, accept="text/plain", content_type="application/json", **kwargs
    ):
        if 'ApiKey' in self.session.headers or 'api-key' in self.session.headers:
            return {
                "accept": accept,
                "Content-Type": content_type,
                **self.session.headers, 
                **kwargs}
        else:
            auth = "Bearer " + self.get_auth_token()
            headers = {
                "accept": accept,
                "Authorization": auth,
                "Ocp-Apim-Subscription-Key": self.apim_subscription_key,
                "Content-Type": content_type,
            }
            return {**headers, **kwargs}

    def get_auth_token(self):
        if self.certificate_path:
            credential = CertificateCredential(
                self.certificate_tenant,
                self.azure_client_id,
                self.certificate_path,
                password=self.certificate_password
            )
            token = credential.get_token(f"api://{self.certificate_scope}/.default")
        else:
            credential = DefaultAzureCredential()
            token = credential.get_token(f"api://{self.azure_client_id}/.default")
        return token.token

    def create_usecase(self, usecase_config):
        """
        Create a new use case.

        Args:
            usecase_config (dict): The configuration for the new use case.

        Returns:
            dict: The response from the API.
        """
        url = f"{self.base_url}/api/admin/usecases"
        self.logger.debug("POST %s with data: %s", url, usecase_config)
        response = self.session.post(
            url, headers=self.build_headers(), data=json.dumps(usecase_config)
        )
        self.logger.debug("Response: %s", response.text)
        return response.json()

    def delete_usecase(self, usecase_id):
        """
        Delete an existing use case.

        Args:
            usecase_id (str): The ID of the use case to delete.

        Returns:
            int: The status code of the response.
        """
        url = f"{self.base_url}/api/admin/{usecase_id}"
        self.logger.debug("DELETE %s", url)
        response = self.session.delete(url, headers=self.build_headers())
        self.logger.debug("Response status code: %s", response.status_code)
        return response.status_code

    def bulk_chat(self, usecase_id, file_path):
        """
        Perform a bulk chat operation.

        Args:
            usecase_id (str): The ID of the use case.
            file_path (str): The path to the file to upload.

        Returns:
            dict: The response from the API.
        """
        url = f"{self.base_url}/api/usecases/{usecase_id}/chat/bulk"
        self.logger.debug("POST %s with file: %s", url, file_path)
        with open(file_path, "rb") as f:
            files = {"file": f}
        response = self.session.post(url, headers=self.build_headers(), files=files)
        self.logger.debug("Response: %s", response.text)
        return response.json()

