    def chat(self, usecase_id: str, completion_v1: Dict[str, Any]) -> Dict[str, Any]:
        """Perform a chat operation.
        
        Args:
            usecase_id (str): The ID of the use case
            completion_v1 (dict): Chat completion data containing:
                - messages: List of message objects
                - temperature: Float value
                - max_tokens: Integer value
                
        Returns:
            dict: The API response
            
        Raises:
            JSONDecodeError: If completion_v1 contains non-serializable data
        """
        url = f"{self.base_url}/api/usecases/{usecase_id}/chat"
        
        try:
            # Ensure completion_v1 is a dict
            if not isinstance(completion_v1, dict):
                raise TypeError("completion_v1 must be a dictionary")
                
            # Convert to JSON-serializable format
            json_data = json.dumps(completion_v1, default=str)
            
            self.logger.debug("POST %s with data: %s", url, json_data)
            response = self.session.post(
                url,
                headers=self.build_headers(),
                data=json_data
            )
            self.logger.debug("Response: %s", response.text)
            return response.json()
            
        except json.JSONDecodeError as e:
            self.logger.error("Failed to encode completion_v1: %s", str(e))
            raise
    
    def chat_v2(self, usecase_id: str, completion_v2: Dict[str, Any]) -> Dict[str, Any]:
        """Perform a v2 chat operation.

        Args:
            usecase_id (str): The ID of the use case.
            completion_v2 (dict): Request payload for the v2 chat endpoint.
                The payload is passed through to the API as-is and should
                follow the server schema. Common fields include:
                - prompt: Object containing role/parts/toolCallResponses/intent
                - history: List of prior user/agent turns
                - groundings: List of grounding IDs
                - functions: List of tool/function definitions
                - filters: Optional filter object
                - context: Optional context object (e.g., Filename)

        Returns:
            dict: The API response.

        Raises:
            TypeError: If completion_v2 is not a dictionary.
            JSONDecodeError: If completion_v2 contains non-serializable data.
        """
        url = f"{self.base_url}/api/v2/usecases/{usecase_id}/chat"
        
        try:
            if not isinstance(completion_v2, dict):
                raise TypeError("completion_v2 must be a dictionary")
                
            # Convert to JSON-serializable format
            json_data = json.dumps(completion_v2, default=str)
            
            self.logger.debug("POST %s with data: %s", url, json_data)
            response = self.session.post(
                url,
                headers=self.build_headers(),
                data=json_data
            )
            self.logger.debug("Response: %s", response.text)
            return response.json()
            
        except json.JSONDecodeError as e:
            self.logger.error("Failed to encode completion_v2: %s", str(e))
            raise
    
    def stream(self, usecase_id, completion_v1):
        """
        Perform a chat streaming operation.

        Args:
            usecase_id (str): The ID of the use case.
            completion_v1 (dict): The chat completion data.

        Returns:
            dict: The response from the API.
        """
        url = f"{self.base_url}/api/usecases/{usecase_id}/chat/stream"
        self.logger.info("POST %s with data: %s", url, completion_v1)
        response = self.session.post(
            url, headers=self.build_headers(), data=json.dumps(completion_v1)
        )
        for chunk in response:
            yield chunk

