    def get_usecase_tokens(self, usecase_id, start_date=None, end_date=None, unit_type=None):
        """
        Get token usage for a specific use case.

        Args:
            usecase_id (str): The ID of the use case.
            start_date (str, optional): Start date for token usage data (ISO format).
            end_date (str, optional): End date for token usage data (ISO format).
            unit_type (str, optional): Unit type for grouping (one of Day, Month, Year).

        Returns:
            dict: The response from the API containing token usage information.
        """
        url = f"{self.base_url}/api/admin/usecases/{usecase_id}/tokens"
        params = {}
        if start_date:
            params["startDate"] = start_date
        if end_date:
            params["endDate"] = end_date
        if unit_type:
            valid_unit_types = ["Day", "Month", "Year"]
            if unit_type.lower() in [t.lower() for t in valid_unit_types]:
                # Find the correct case version
                for valid_type in valid_unit_types:
                    if unit_type.lower() == valid_type.lower():
                        params["unitType"] = valid_type
                        break
            else:
                error_msg = f"Invalid unit_type: '{unit_type}'. Must be one of {valid_unit_types}"
                self.logger.error(error_msg)
                raise ValueError(error_msg)
            
        self.logger.debug("GET %s with params: %s", url, params)
        response = self.session.get(url, headers=self.build_headers(), params=params)
        self.logger.debug("Response: %s", response.text)
        return response.json()

