    def upload_file(self, usecase_id, file_path, allow_override=False):
        """
        Upload a file to a use case (using the files endpoint).

        Args:
            usecase_id (str): The ID of the use case.
            file_path (str): The path to the file to upload.
            allow_override (bool, optional): Whether to allow overriding existing files.

        Returns:
            dict: The response from the API.
        """
        url = f"{self.base_url}/api/usecases/{usecase_id}/files"
        params = {}
        if allow_override:
            params["allowOverride"] = "true"
            
        self.logger.debug("POST %s with file: %s and params: %s", url, file_path, params)
        with open(file_path, "rb") as f: 
            files = {"file": f}
        response = self.session.post(url, headers=self.build_headers(), files=files, params=params)
        self.logger.debug("Response: %s", response.text)
        return response.json()

